const { useCallback, useEffect, useRef, useState } = React;

const CASE = {
  mode: "replace",
  base: "translateX(30px) rotate(45deg)",
  effect: "translateX(100px)",
  end: "translateX(100px)",
  rule: "只取 effect value，underlying value 不参与合成，未声明的 rotate 回到 0deg",
  baseAngle: 45,
  compare: "accumulate",
};
const DURATION_MS = 2000;
const TICKS = [0, 50, 100, 150];
const ANIMATION = `cb-comp-replace-move ${DURATION_MS}ms linear infinite alternate paused`;

const STYLE = `
  @scope {
    .cb-range { accent-color: var(--tau-accent); }
  }
  @keyframes cb-comp-replace-move {
    to { transform: translateX(100px); }
  }
`;

// 把计算后的 matrix 还原成 translate + rotate 读数；matrix 里 360deg 与 0deg 相同，按上一帧角度展开成连续值
const readTransform = (element, previousAngle) => {
  const raw = getComputedStyle(element).transform;
  const values = raw.match(/matrix\(([^)]+)\)/)?.[1].split(",").map(Number);
  if (!values) return { text: raw && raw !== "none" ? raw : CASE.base, angle: previousAngle };
  const [a, b, , , x, y] = values;
  const rawAngle = (Math.atan2(b, a) * 180) / Math.PI;
  const angle = Math.round(rawAngle + 360 * Math.round((previousAngle - rawAngle) / 360));
  const move = Math.abs(y) < 0.5 ? `translateX(${Math.round(x)}px)` : `translate(${Math.round(x)}px, ${Math.round(y)}px)`;
  return { text: `${move} rotate(${angle}deg)`, angle };
};

const Chip = ({ children }) => (
  <code className="min-w-0 break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">{children}</code>
);

const Lane = ({ mode, boxRef, readout, boxClassName }) => (
  <div className="flex flex-col gap-1.5">
    <div className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1">
      <span className="font-tau-mono text-tau-sm text-ink-2">animation-composition: {mode}</span>
      <span className="min-w-0 break-all font-tau-mono text-tau-sm text-ink-3">{readout}</span>
    </div>
    <div className="relative h-[84px] overflow-hidden">
      {TICKS.map(tick => (
        <div key={tick} className="absolute bottom-0 flex -translate-x-1/2 flex-col items-center" style={{ left: 28 + tick }}>
          <span className="font-tau-mono text-tau-tiny text-ink-3">{tick}</span>
          <span className="h-1.5 w-px bg-line-1" />
        </div>
      ))}
      <div className="absolute inset-x-0 bottom-0 h-px bg-line-2" />
      <div
        className="absolute left-2 top-3 size-10 rounded-tau-sm border border-dashed border-ink-3"
        style={{ transform: CASE.base }}
      />
      <div
        ref={boxRef}
        className={`absolute left-2 top-3 size-10 rounded-tau-sm ${boxClassName}`}
        style={{ transform: CASE.base, animation: ANIMATION, animationComposition: mode }}
      >
        <span className="absolute left-1.5 top-1.5 size-2 rounded-full bg-surface" />
      </div>
    </div>
  </div>
);

const Component = () => {
  const stageRef = useRef(null);
  const mainRef = useRef(null);
  const compareRef = useRef(null);
  const timeRef = useRef(0);
  const frameRef = useRef(0);
  const anglesRef = useRef({ main: CASE.baseAngle, compare: CASE.baseAngle });
  const [playing, setPlaying] = useState(true);
  const [showCompare, setShowCompare] = useState(false);
  const [time, setTime] = useState(0);
  const [readouts, setReadouts] = useState({ main: CASE.base, compare: CASE.base });

  // 所有 CSS 动画都暂停，由同一个时钟写入 currentTime，保证两条轨道同步、可拖动
  const apply = useCallback(next => {
    timeRef.current = next;
    stageRef.current?.getAnimations?.({ subtree: true }).forEach(animation => {
      animation.currentTime = next;
    });
    setTime(next);
    const nextReadouts = {};
    for (const [key, ref] of [["main", mainRef], ["compare", compareRef]]) {
      if (!ref.current) {
        anglesRef.current[key] = CASE.baseAngle;
        nextReadouts[key] = CASE.base;
        continue;
      }
      const reading = readTransform(ref.current, anglesRef.current[key]);
      anglesRef.current[key] = reading.angle;
      nextReadouts[key] = reading.text;
    }
    setReadouts(nextReadouts);
  }, []);

  useEffect(() => {
    apply(timeRef.current);
    if (!playing) return;
    let last = 0;
    const tick = now => {
      if (last) apply((timeRef.current + now - last) % (DURATION_MS * 2));
      last = now;
      frameRef.current = requestAnimationFrame(tick);
    };
    frameRef.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frameRef.current);
  }, [playing, showCompare, apply]);

  const progress = time <= DURATION_MS ? time / DURATION_MS : 2 - time / DURATION_MS;
  const scrub = event => {
    setPlaying(false);
    apply((Number(event.target.value) / 100) * DURATION_MS);
  };

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div ref={stageRef} className="flex min-w-0 flex-col gap-4 rounded-tau-md border border-line-1 p-4">
          <Lane mode={CASE.mode} boxRef={mainRef} readout={readouts.main} boxClassName="bg-accent shadow-card" />
          {showCompare && (
            <Lane mode={CASE.compare} boxRef={compareRef} readout={readouts.compare} boxClassName="border-2 border-tag-3 bg-tag-3-soft" />
          )}
          <div className="flex items-center gap-2 text-tau-sm text-ink-3">
            <span className="size-3 rounded-tau-sm border border-dashed border-ink-3" />
            underlying value 的位置
          </div>
        </div>
        <dl className="m-0 flex flex-col gap-2.5 rounded-tau-md border border-line-1 p-3">
          <div className="flex flex-col gap-1">
            <dt className="text-tau-sm text-ink-3">underlying value</dt>
            <dd className="m-0 flex"><Chip>transform: {CASE.base}</Chip></dd>
          </div>
          <div className="flex flex-col gap-1">
            <dt className="text-tau-sm text-ink-3">effect value（to 帧）</dt>
            <dd className="m-0 flex"><Chip>transform: {CASE.effect}</Chip></dd>
          </div>
          <div className="flex flex-col gap-1">
            <dt className="text-tau-sm text-ink-3">{CASE.mode} 的合成规则</dt>
            <dd className="m-0 text-tau-meta text-ink-2">{CASE.rule}</dd>
          </div>
          <div className="flex flex-col gap-1 border-t border-line-2 pt-2.5">
            <dt className="text-tau-sm text-ink-3">终点等价于</dt>
            <dd className="m-0 flex"><Chip>transform: {CASE.end}</Chip></dd>
          </div>
        </dl>
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <ui.Button variant="secondary" size="sm" icon={playing ? icons.Pause : icons.Play} onClick={() => setPlaying(value => !value)}>
          {playing ? "暂停" : "播放"}
        </ui.Button>
        <label className="flex min-w-[200px] flex-1 items-center gap-3">
          <span className="shrink-0 text-tau-sm text-ink-3">进度</span>
          <input
            type="range"
            min={0}
            max={100}
            value={Math.round(progress * 100)}
            onChange={scrub}
            className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
          />
          <span className="w-10 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{Math.round(progress * 100)}%</span>
        </label>
        <ui.Switch size="sm" checked={showCompare} onCheckedChange={setShowCompare} label={`对照 ${CASE.compare}`} />
      </div>
    </div>
  );
};

