            min={0}
            max={100}
            value={Math.round(progress * 100)}
            onChange={scrub}
            className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
          />
          <span className="w-10 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{Math.round(progress * 100)}%</span>
        </label>
        <ui.Switch size="sm" checked={showCompare} onCheckedChange={setShowCompare} label={`对照 ${CASE.compare}`} />
      </div>
    </div>
  );
};

