const { useCallback, useEffect, useRef, useState } = React;

const BASE = "translateX(20px)";
const CYCLE_MS = 4000;
const TICKS = [0, 50, 100, 150];
const MODES = ["replace", "add", "accumulate"].map(value => ({ value, label: value }));
const SPIN = "cb-comp-stack-spin 2000ms linear infinite paused";
const SLIDE = "cb-comp-stack-slide 2000ms ease-in-out infinite alternate paused";
const LAYERS = ["spin", "stack"];

const STYLE = `
  @scope {
    .cb-range { accent-color: var(--tau-accent); }
  }
  @keyframes cb-comp-stack-spin {
    to { transform: rotate(360deg); }
  }
  @keyframes cb-comp-stack-slide {
    to { transform: translateX(80px); }
  }
`;

// 把计算后的 matrix 还原成 translate + rotate；360deg 与 0deg 的 matrix 相同，按上一帧角度展开成连续值
const readTransform = (element, previousAngle) => {
  const raw = getComputedStyle(element).transform;
  const values = raw.match(/matrix\(([^)]+)\)/)?.[1].split(",").map(Number);
  if (!values) return { text: raw && raw !== "none" ? raw : BASE, angle: previousAngle };
  const [a, b, , , x, y] = values;
  const rawAngle = (Math.atan2(b, a) * 180) / Math.PI;
  const angle = Math.round(rawAngle + 360 * Math.round((previousAngle - rawAngle) / 360));
  const move = Math.abs(y) < 0.5 ? `translateX(${Math.round(x)}px)` : `translate(${Math.round(x)}px, ${Math.round(y)}px)`;
  return { text: `${move} rotate(${angle}deg)`, angle };
};

const Chip = ({ children }) => (
  <code className="min-w-0 break-all rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">{children}</code>
);

const Step = ({ index, swatch, title, control, readout }) => (
  <li className="flex gap-2.5">
    <span className="mt-0.5 grid size-5 shrink-0 place-items-center rounded-full bg-hover font-tau-mono text-tau-tiny text-ink-2">{index}</span>
    <div className="flex min-w-0 flex-1 flex-col gap-1.5">
      <div className="flex flex-wrap items-center gap-2">
        <span className={`size-3 shrink-0 rounded-tau-sm ${swatch}`} />
        <span className="font-tau-mono text-tau-sm text-ink-1">{title}</span>
        {control}
      </div>
      <div className="flex"><Chip>{readout}</Chip></div>
    </div>
  </li>
);

const Box = ({ boxRef, className, style }) => (
  <div ref={boxRef} className={`absolute left-4 top-[calc(50%-20px)] size-10 rounded-tau-sm ${className}`} style={{ transform: BASE, ...style }}>
    <span className="absolute left-1.5 top-1.5 size-2 rounded-full bg-surface" />
  </div>
);

const Component = () => {
  const stageRef = useRef(null);
  const boxRefs = { spin: useRef(null), stack: useRef(null) };
  const anglesRef = useRef({ spin: 0, stack: 0 });
  const timeRef = useRef(0);
  const frameRef = useRef(0);
  const [spinMode, setSpinMode] = useState("add");
  const [slideMode, setSlideMode] = useState("accumulate");
  const [showMiddle, setShowMiddle] = useState(true);
  const [playing, setPlaying] = useState(true);
  const [time, setTime] = useState(0);
  const [readouts, setReadouts] = useState({ spin: BASE, stack: BASE });

  // 所有 CSS 动画都暂停，由同一个时钟写入 currentTime，各层同步且可以拖动
  const apply = useCallback(next => {
    timeRef.current = next;
    stageRef.current?.getAnimations?.({ subtree: true }).forEach(animation => {
      animation.currentTime = next;
    });
    setTime(next);
    const nextReadouts = {};
    for (const key of LAYERS) {
      const element = boxRefs[key].current;
      if (!element) {
        anglesRef.current[key] = 0;
        nextReadouts[key] = BASE;
        continue;
      }
      const reading = readTransform(element, anglesRef.current[key]);
      anglesRef.current[key] = reading.angle;
      nextReadouts[key] = reading.text;
    }
    setReadouts(nextReadouts);
  }, []);

  useEffect(() => {
    apply(timeRef.current);
    if (!playing) return;
    let last = 0;
    const tick = now => {
      if (last) apply((timeRef.current + now - last) % CYCLE_MS);
      last = now;
      frameRef.current = requestAnimationFrame(tick);
    };
    frameRef.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frameRef.current);
  }, [playing, showMiddle, spinMode, slideMode, apply]);

  const scrub = event => {
    setPlaying(false);
    apply(Number(event.target.value));
  };
  const reset = () => {
    setSpinMode("add");
    setSlideMode("accumulate");
  };
  const modeSelect = (label, value, onChange) => (
    <ui.Select size="sm" aria-label={label} options={MODES} value={value} onValueChange={onChange} />
  );

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div ref={stageRef} className="relative h-[220px] min-w-0 overflow-hidden rounded-tau-md border border-line-1">
          {TICKS.map(tick => (
            <div key={tick} className="absolute bottom-0 flex -translate-x-1/2 flex-col items-center" style={{ left: 36 + tick }}>
              <span className="font-tau-mono text-tau-tiny text-ink-3">{tick}</span>
              <span className="h-1.5 w-px bg-line-1" />
            </div>
          ))}
          <div className="absolute inset-x-0 top-1/2 h-px bg-line-2" />
          <Box className="border border-dashed border-ink-3" />
          {showMiddle && (
            <Box
              boxRef={boxRefs.spin}
              className="border-2 border-tag-2 bg-tag-2-soft"
              style={{ animation: SPIN, animationComposition: spinMode }}
            />
          )}
          <Box
            boxRef={boxRefs.stack}
            className="bg-accent shadow-card"
            style={{ animation: `${SPIN}, ${SLIDE}`, animationComposition: `${spinMode}, ${slideMode}` }}
          />
        </div>
        <div className="flex flex-col gap-3 rounded-tau-md border border-line-1 p-3">
          <span className="text-tau-sm text-ink-3">effect stack，自下而上逐层合成</span>
          <ol className="m-0 flex list-none flex-col gap-3 p-0">
            <Step index={1} swatch="border border-dashed border-ink-3" title="underlying value" readout={BASE} />
            <Step
              index={2}
              swatch="border-2 border-tag-2 bg-tag-2-soft"
              title="+ spin"
              control={modeSelect("spin 的合成方式", spinMode, setSpinMode)}
              readout={readouts.spin}
            />
            <Step
              index={3}
              swatch="bg-accent"
              title="+ slide"
              control={modeSelect("slide 的合成方式", slideMode, setSlideMode)}
              readout={readouts.stack}
            />
          </ol>
        </div>
      </div>
      <pre className="m-0 overflow-x-auto rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
        <div>{".box {"}</div>
        <div>{"  transform: translateX(20px);"}</div>
        <div>{"  animation: spin 2s linear infinite, slide 2s ease-in-out infinite alternate;"}</div>
        <div>
          {"  animation-composition: "}
          <span className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">{spinMode}</span>
          {", "}
          <span className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">{slideMode}</span>
          {";"}
        </div>
        <div>{"}"}</div>
      </pre>
      <div className="flex flex-wrap items-center gap-3">
        <ui.Button variant="secondary" size="sm" icon={playing ? icons.Pause : icons.Play} onClick={() => setPlaying(value => !value)}>
          {playing ? "暂停" : "播放"}
        </ui.Button>
        <label className="flex min-w-[200px] flex-1 items-center gap-3">
          <span className="shrink-0 text-tau-sm text-ink-3">时间</span>
          <input
            type="range"
            min={0}
            max={CYCLE_MS}
            step={20}
            value={Math.round(time)}
            onChange={scrub}
            className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
          />
          <span className="w-10 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{(time / 1000).toFixed(1)}s</span>
        </label>
        <ui.Switch size="sm" checked={showMiddle} onCheckedChange={setShowMiddle} label="显示中间层" />
        <ui.Button variant="ghost" size="sm" icon={icons.RotateCcw} onClick={reset}>
          恢复正文示例
        </ui.Button>
      </div>
    </div>
  );
};
